function readAuthHandoff(){try{const saved=JSON.parse(sessionStorage.getItem('dlr-auth-handoff')||'null');if(!saved?.token||!saved?.user)return null;if(saved.token.split('.').length!==3)return saved;let encoded=saved.token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');encoded+='='.repeat((4-encoded.length%4)%4);const payload=JSON.parse(atob(encoded));if(Number(payload.exp||0)*1000<=Date.now()+5000){sessionStorage.removeItem('dlr-auth-handoff');return null;}return saved;}catch{return null;}}
async function resetExpiredSession(){if(!needsSessionReset)return;try{await client.auth.signOut();}catch{}client=newClient();user=null;needsSessionReset=false;translate();}
async function token(){const handoff=readAuthHandoff();if(handoff){user=handoff.user;handoffToken=handoff.token;return handoff.token;}let lastError=null;for(let attempt=0;attempt<5;attempt++){try{const response=await fetch(cfg.authUrl+'/token',{credentials:'include',cache:'no-store',headers:handoffToken?{authorization:'Bearer '+handoffToken}:{}}),data=await response.json();if(response.ok&&data?.token){handoffToken=data.token;return data.token;}}catch(error){lastError=error;}const r=await client.auth.token();if(!r.error&&r.data?.token){handoffToken=r.data.token;return r.data.token;}lastError=r.error||lastError;const restored=await client.auth.getSession();if(restored.error)lastError=restored.error;if(restored.data?.user)user=restored.data.user;if(attempt<4)await new Promise(resolve=>setTimeout(resolve,150*(attempt+1)));}if(handoffToken)return handoffToken;throw lastError||new Error('Session expired. Log in again.');}
async function api(path,method='GET',body){const auth=user?{'authorization':'Bearer '+await token()}:{};const r=await fetch(cfg.apiUrl+path,{method,headers:{'content-type':'application/json',...auth},body:body===undefined?undefined:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed');return data;}
