function maxBrackets(bowlers,prop){const pool=bowlers.map(b=>({id:b.id,limit:Math.max(0,Math.floor(Number(b.events?.[prop])||0)),assigned:0}));if(pool.filter(x=>x.limit).length<8)return 0;let low=0,high=Math.floor(pool.reduce((n,x)=>n+x.limit,0)/8);while(low<high){const mid=Math.ceil((low+high)/2);if(pool.reduce((n,x)=>n+Math.min(x.limit,mid),0)>=8*mid)low=mid;else high=mid-1;}return low;}
const pairKey=(a,b)=>[a,b].sort().join('|');
function allPairs(ids){if(!ids.length)return[[]];const [a,...rest]=ids,out=[];for(let i=0;i<rest.length;i++){for(const tail of allPairs(rest.filter((_,j)=>j!==i)))out.push([[a,rest[i]],...tail]);}return out;}
function seed(ids,opponents){const options=allPairs(ids),best=Math.min(...options.map(ps=>ps.reduce((n,[a,b])=>n+(opponents.get(pairKey(a,b))||0),0))),choice=options.filter(ps=>ps.reduce((n,[a,b])=>n+(opponents.get(pairKey(a,b))||0),0)===best)[Math.floor(Math.random()*options.filter(ps=>ps.reduce((n,[a,b])=>n+(opponents.get(pairKey(a,b))||0),0)===best).length)];choice.forEach(([a,b])=>opponents.set(pairKey(a,b),(opponents.get(pairKey(a,b))||0)+1));return choice.flat();}
function buildBrackets(bowlers,prop,sharedGroups=new Map(),opponents=new Map()){const count=maxBrackets(bowlers,prop);if(!count)return[];const pool=bowlers.map(b=>({id:b.id,limit:Math.min(count,Math.max(0,Math.floor(Number(b.events?.[prop])||0))),assigned:0}));for(let i=0;i<count*8;i++){const eligible=pool.filter(x=>x.assigned<x.limit).sort((a,b)=>(a.assigned/a.limit)-(b.assigned/b.limit)||Math.random()-.5);eligible[0].assigned++;}const result=Array.from({length:count},()=>[]);pool.sort((a,b)=>b.assigned-a.assigned||Math.random()-.5).forEach(p=>{for(let n=0;n<p.assigned;n++){const slots=result.map((ids,i)=>({ids,i})).filter(x=>x.ids.length<8&&!x.ids.includes(p.id)).sort((a,b)=>a.ids.reduce((n,x)=>n+(sharedGroups.get(pairKey(p.id,x))||0),0)-b.ids.reduce((n,x)=>n+(sharedGroups.get(pairKey(p.id,x))||0),0)||a.ids.length-b.ids.length);if(!slots[0])throw new Error('Could not place all bracket entries.');slots[0].ids.forEach(x=>sharedGroups.set(pairKey(p.id,x),(sharedGroups.get(pairKey(p.id,x))||0)+1));slots[0].ids.push(p.id);}});return result.map(ids=>seed(ids,opponents));}
const bowler=id=>state.bowlers.find(b=>b.id===id),has=(b,g)=>{const raw=b?.scores?.[g-1];return raw!==null&&raw!==''&&raw!==undefined&&Number.isFinite(Number(raw));},score=(b,g,withHandicap=true)=>has(b,g)?Number(b.scores[g-1])+(withHandicap?Number(b.handicap||0):0):null;
function duel(ids,game,scratch=false,maxGame=game){const players=ids.map(bowler).filter(Boolean);if(players.length<2)return null;for(let decidingGame=game;decidingGame<=maxGame;decidingGame++){if(players.some(b=>!has(b,decidingGame)))return null;const high=Math.max(...players.map(b=>score(b,decidingGame,!scratch))),w=players.filter(b=>score(b,decidingGame,!scratch)===high);if(w.length===1)return w[0].id;}return null;}
function finalRanking(ids,key){const games=WINDOWS[key],scratch=SCRATCH_KEYS.has(key),players=ids.map(bowler).filter(Boolean);if(players.length<2||players.some(player=>games.some(game=>!has(player,game))))return null;const metrics=player=>[score(player,games[2],!scratch),games.reduce((sum,game)=>sum+score(player,game,true),0),Math.max(...games.map(game=>score(player,game,true)))];return players.map(player=>({id:player.id,metrics:metrics(player)})).sort((a,b)=>b.metrics[0]-a.metrics[0]||b.metrics[1]-a.metrics[1]||b.metrics[2]-a.metrics[2]||bowler(a.id).name.localeCompare(bowler(b.id).name));}
function bracketResult(ids,key){const games=WINDOWS[key],scratch=SCRATCH_KEYS.has(key),maxGame=SUNDAY_KEYS.includes(key)?7:4,r1=[];for(let i=0;i<8;i+=2)r1.push(duel(ids.slice(i,i+2),games[0],scratch,maxGame));const r2=[duel(r1.slice(0,2),games[1],scratch,maxGame),duel(r1.slice(2,4),games[1],scratch,maxGame)],ranking=finalRanking(r2,key);if(!ranking)return null;const same=(a,b)=>a.metrics.every((value,index)=>value===b.metrics[index]),winnerGroup=ranking.filter(entry=>same(entry,ranking[0])),secondGroup=winnerGroup.length===1&&ranking[1]?ranking.filter(entry=>same(entry,ranking[1])):[];return{winner:winnerGroup[0].id,winners:winnerGroup.map(x=>x.id),second:secondGroup[0]?.id||null,seconds:secondGroup.map(x=>x.id),r1,r2,ranking};}
function bracketAwards(){const out=[];for(const key of Object.keys(WINDOWS))(state.brackets[key]||[]).forEach((ids,i)=>{const r=bracketResult(ids,key);if(!r)return;const scratch=SCRATCH_KEYS.has(key),places=[cents(scratch?state.config.scratchBracketFirst:state.config.bracketFirst),cents(scratch?state.config.scratchBracketSecond:state.config.bracketSecond)];for(let rank=0;rank<r.ranking.length&&rank<places.length;){let end=rank+1;while(end<r.ranking.length&&r.ranking[end].metrics.every((value,index)=>value===r.ranking[rank].metrics[index]))end++;const pool=places.slice(rank,Math.min(end,places.length)).reduce((sum,value)=>sum+value,0),share=Math.floor(pool/(end-rank)),remainder=pool%(end-rank);for(let j=rank;j<end;j++)out.push({id:r.ranking[j].id,category:key,description:`${TITLES[key]} #${i+1} · ${rank+1}${end-rank>1?' tie':''}`,amount:share+(j-rank<remainder?1:0)});rank=end;}});return out;}
function rankedAwards(entries,value,places,description,category){const sorted=entries.filter(x=>Number.isFinite(value(x))).sort((a,b)=>value(b)-value(a)||a.name.localeCompare(b.name)),out=[];for(let i=0;i<sorted.length&&i<places.length;){let end=i+1;while(end<sorted.length&&value(sorted[end])===value(sorted[i]))end++;const pool=places.slice(i,Math.min(end,places.length)).reduce((n,x)=>n+cents(x),0),share=Math.floor(pool/(end-i));for(let j=i;j<end;j++)out.push({id:sorted[j].id,category,description:`${description} · ${i+1}${end-i>1?' tie':''} (${value(sorted[j])})`,amount:share+(j-i<pool%(end-i)?1:0)});i=end;}return out;}
function highAwards(){const sat=state.bowlers.filter(b=>b.events.satHigh&&[1,2,3,4].every(g=>has(b,g))),sun=state.bowlers.filter(b=>b.events.sunHigh&&[5,6,7].every(g=>has(b,g)));return[...rankedAwards(sat,b=>Math.max(...[1,2,3,4].map(g=>score(b,g))),[state.config.satHighPayout],'Saturday High Game','satHigh'),...rankedAwards(sun,b=>Math.max(...[5,6,7].map(g=>score(b,g))),[state.config.sunHighPayout],'Sunday High Game','sunHigh')];}
