function assigned(key,bid){return (state.brackets[key]||[]).reduce((n,ids)=>n+ids.filter(x=>x===bid).length,0);}
function charges(b){const c=[];for(const key of Object.keys(WINDOWS)){const n=assigned(key,b.id),price=SCRATCH_KEYS.has(key)?state.config.scratchBracketBuyin:state.config.bracketBuyin;if(n)c.push({label:`${TITLES[key]}: ${n} × $${Number(price).toFixed(2)}`,amount:n*cents(price),day:SUNDAY_KEYS.includes(key)?'sunday':'saturday'});}if(b.events.satHigh)c.push({label:`Saturday High Game: $${Number(state.config.satHighBuyin).toFixed(2)}`,amount:cents(state.config.satHighBuyin),day:'saturday'});if(b.events.sunHigh)c.push({label:`Sunday High Game: $${Number(state.config.sunHighBuyin).toFixed(2)}`,amount:cents(state.config.sunHighBuyin),day:'sunday'});const teamCount=state.teams.filter(ids=>ids.includes(b.id)).length;if(teamCount)c.push({label:`Doubles: ${teamCount} × $${Number(state.config.doublesBuyin).toFixed(2)}`,amount:teamCount*cents(state.config.doublesBuyin),day:'saturday'});return c;}
function personal(b){const cs=charges(b),wins=awards().filter(a=>a.id===b.id),saturdayDue=cs.filter(x=>x.day==='saturday').reduce((n,x)=>n+x.amount,0),sundayDue=cs.filter(x=>x.day==='sunday').reduce((n,x)=>n+x.amount,0),due=saturdayDue+sundayDue,won=wins.reduce((n,x)=>n+x.amount,0),outstanding=(b.saturdayPaid?0:saturdayDue)+(b.sundayPaid?0:sundayDue);return{id:b.id,name:b.name,paid:!!b.saturdayPaid&&!!b.sundayPaid,saturdayPaid:!!b.saturdayPaid,sundayPaid:!!b.sundayPaid,charges:cs,winnings:wins,saturdayDue,sundayDue,due,won,outstanding,settlement:won-outstanding};}
function snapshot(){const allAwards=awards(),people=state.bowlers.map(personal),summary=competitionMetrics({...state,awards:allAwards});return{results:{format:FORMAT,bowlers:state.bowlers,brackets:state.brackets,teams:state.teams,config:state.config,awards:allAwards,summary},personal:state.bowlers.filter(b=>b.email).map(b=>({email:b.email,data:personal(b)})),people};}
function competitionMetrics(data=state){const brackets=data.brackets||{},bowlers=data.bowlers||[],config=data.config||{},handicapKeys=['satEarly','satLate','sunday'],scratchKeys=['scratchEarly','scratchLate','scratchSunday'],bracketCount=keys=>keys.reduce((n,key)=>n+(brackets[key]?.length||0),0),entryCount=keys=>keys.reduce((n,key)=>n+(brackets[key]||[]).reduce((sum,ids)=>sum+ids.filter(Boolean).length,0),0),handicapBrackets=bracketCount(handicapKeys),scratchBrackets=bracketCount(scratchKeys),highGameEntries=bowlers.reduce((n,b)=>n+(b.events?.satHigh?1:0)+(b.events?.sunHigh?1:0),0),doublesTeams=(data.teams||[]).length,totalIncome=Math.round(entryCount(handicapKeys)*Number(config.bracketBuyin||0)*100+entryCount(scratchKeys)*Number(config.scratchBracketBuyin||0)*100+bowlers.filter(b=>b.events?.satHigh).length*Number(config.satHighBuyin||0)*100+bowlers.filter(b=>b.events?.sunHigh).length*Number(config.sunHighBuyin||0)*100+doublesTeams*2*Number(config.doublesBuyin||0)*100),totalPayout=(data.awards||awards()).reduce((n,a)=>n+Number(a.amount||0),0);return{handicapBrackets,scratchBrackets,highGameEntries,doublesTeams,totalIncome,totalPayout,totalProfit:totalIncome-totalPayout};}
function competitionSummaryMarkup(data=state){const summary=data.summary||competitionMetrics(data);return[['Handicap brackets played',summary.handicapBrackets],['Scratch brackets played',summary.scratchBrackets],['High Game entries',summary.highGameEntries],['Doubles teams played',summary.doublesTeams],['Total income',money(summary.totalIncome)],['Total payout',money(summary.totalPayout)],['Total profit',money(summary.totalProfit)]].map(([label,value],index)=>`<div class="summary-metric ${index===6?'profit':''}"><span>${esc(tr(label))}</span><strong class="${index===6?(summary.totalProfit<0?'balance-negative':summary.totalProfit>0?'balance-positive':'balance-zero'):''}">${value}</strong></div>`).join('');}
function scheduleSave(){if(archiveMode)return;queued=true;$('saveState').textContent='Changes not saved yet.';clearTimeout(saveTimer);saveTimer=setTimeout(()=>void save().catch(()=>{}),500);}
async function save(){if(saving||!queued||!competition)return;saving=true;queued=false;$('saveState').textContent='Saving…';try{const snap=snapshot(),saved=await api('/save?id='+encodeURIComponent(competition.id),'POST',{state,results:snap.results,personal:snap.personal,eventDate:new Date().toLocaleDateString('en-CA')});if(saved.updatedAt)state._serverUpdatedAt=saved.updatedAt;$('saveState').textContent=queued?'Saving latest changes…':'Saved to Neon.';}catch(e){queued=true;$('saveState').textContent='Could not save: '+e.message;throw e;}finally{saving=false;if(queued)saveTimer=setTimeout(()=>void save().catch(()=>{}),800);}}
async function flushSave(){clearTimeout(saveTimer);while(saving)await new Promise(resolve=>setTimeout(resolve,50));if(queued)await save();while(saving||queued){while(saving)await new Promise(resolve=>setTimeout(resolve,50));if(queued)await save();}}
async function saveTournamentSession(){const label=$('dlrSessionLabel').value.trim(),date=$('dlrSessionDate').value;if(!label||!date)throw new Error('Enter a session name and date before saving.');await flushSave();const snap=snapshot();await api('/sessions','POST',{competitionId:competition.id,label,date,state,results:snap.results,personal:snap.personal});$('dlrSessionStatus').textContent=label+' was saved. The current session remains open.';}
async function startTournamentSession(){if(!confirm('Start a new De La Rosa Masters session? The roster, player IDs, emails and handicaps will remain. All entries, payments, brackets, teams and seven-game scores will reset.'))return;await flushSave();const previous=state,next=fresh();next.config={...previous.config};next.language=previous.language;next.bowlers=previous.bowlers.map(b=>({...b,paid:false,saturdayPaid:false,sundayPaid:false,events:{satEarly:0,satLate:0,sunday:0,scratchEarly:0,scratchLate:0,scratchSunday:0,satHigh:false,sunHigh:false,doubles:false},scores:Array(7).fill(null)}));next._serverUpdatedAt=previous._serverUpdatedAt;next._startNewSession=true;state=next;queued=true;try{await flushSave();$('dlrSessionLabel').value='';$('dlrSessionDate').value=new Date().toLocaleDateString('en-CA');$('dlrSessionStatus').textContent='A new session is ready with the roster and handicaps preserved.';document.querySelector('[data-tab="registration"]').click();render();}catch(error){state=previous;render();throw error;}}
const configDefs=[['bracketBuyin','Handicap bracket buy-in, per entry'],['bracketFirst','Handicap bracket 1st place'],['bracketSecond','Handicap bracket 2nd place'],['scratchBracketBuyin','Scratch bracket buy-in, per entry'],['scratchBracketFirst','Scratch bracket 1st place'],['scratchBracketSecond','Scratch bracket 2nd place'],['satHighBuyin','Saturday High Game buy-in'],['satHighPayout','Saturday High Game payout'],['sunHighBuyin','Sunday High Game buy-in'],['sunHighPayout','Sunday High Game payout'],['doublesBuyin','Doubles buy-in, per bowler/team'],['doublesFirst','Doubles 1st place'],['doublesSecond','Doubles 2nd place'],['doublesThird','Doubles 3rd place']];
