function renderConfig(){ $('configForm').innerHTML=configDefs.map(([k,label])=>`<label>${esc(tr(label))} ($)<input name="${k}" type="number" min="0" step=".01" value="${state.config[k]}" required></label>`).join(''); }
function renderEventFields(b={events:{}}){$('eventFields').innerHTML=eventDefs.map(([k,label])=>`<div class="event-box"><label><input type="checkbox" data-event="${k}" ${b.events[k]>0?'checked':''}> ${esc(label)}</label><input data-count="${k}" type="number" min="1" max="99" value="${b.events[k]||1}" ${b.events[k]>0?'':'disabled'}></div>`).join('')+`<div class="event-box"><label><input type="checkbox" data-flag="satHigh" ${b.events.satHigh?'checked':''}> ${esc(tr('Saturday High Game'))}</label></div><div class="event-box"><label><input type="checkbox" data-flag="sunHigh" ${b.events.sunHigh?'checked':''}> ${esc(tr('Sunday High Game'))}</label></div><div class="event-box"><label><input type="checkbox" data-flag="doubles" ${b.events.doubles?'checked':''}> ${esc(tr('Doubles'))}</label></div>`;}
function renderRoster(){$('rosterRows').innerHTML=alphabetical(state.bowlers).map(b=>`<tr><td><strong>${esc(b.name)}</strong>${b.email?`<br><small>${esc(b.email)}</small>`:''}</td><td>${b.handicap}</td><td>${b.events.satEarly||0} / ${b.events.satLate||0} / ${b.events.sunday||0}</td><td>${b.events.scratchEarly||0} / ${b.events.scratchLate||0} / ${b.events.scratchSunday||0}</td><td>${b.events.satHigh?'Sat ':''}${b.events.sunHigh?'Sun':''}</td><td>${state.teams.filter(x=>x.includes(b.id)).length}</td><td><label><input type="checkbox" data-paid-day="saturday" data-paid-id="${b.id}" ${b.saturdayPaid?'checked':''}> ${tr('Paid')}</label></td><td><label><input type="checkbox" data-paid-day="sunday" data-paid-id="${b.id}" ${b.sundayPaid?'checked':''}> ${tr('Paid')}</label></td><td><button class="secondary" data-edit="${b.id}">${tr('Edit')}</button> <button class="danger" data-remove="${b.id}">${tr('Remove')}</button></td></tr>`).join('')||'<tr><td colspan="9">No bowlers registered.</td></tr>';}
function bracketDiagram(ids,key){const games=WINDOWS[key],scratch=SCRATCH_KEYS.has(key),maxGame=SUNDAY_KEYS.includes(key)?7:4,r1=[];for(let i=0;i<8;i+=2)r1.push(duel(ids.slice(i,i+2),games[0],scratch,maxGame));const r2=[duel(r1.slice(0,2),games[1],scratch,maxGame),duel(r1.slice(2,4),games[1],scratch,maxGame)],result=bracketResult(ids,key),finalWinners=result?.winners||[];const slot=(bid,won,lost,game)=>{const b=bowler(bid);return`<div class="slot ${won?'win':lost?'lose':'pending'}">${esc(b?.name||'Pending')}${b&&has(b,game)?` <small>${score(b,game,!scratch)}</small>`:''}</div>`},matches=(players,winners,game)=>players.reduce((html,_,i)=>{if(i%2)return html;const selected=winners[Math.floor(i/2)],won=bid=>Array.isArray(selected)?selected.includes(bid):selected===bid,lost=bid=>!!selected&&!won(bid);return html+`<div class="match-box">${slot(players[i],won(players[i]),lost(players[i]),game)}${slot(players[i+1],won(players[i+1]),lost(players[i+1]),game)}</div>`},'');return`<div class="bracket-diagram"><div class="bracket-round"><h4>Game ${games[0]}</h4>${matches(ids,r1,games[0])}</div><div class="bracket-round"><h4>Game ${games[1]} · Semifinal</h4>${matches(r1,r2,games[1])}</div><div class="bracket-round"><h4>Game ${games[2]} · Final</h4><div class="match-box">${matches(r2,[finalWinners],games[2])}</div></div><div class="bracket-round round-winner"><h4>Winner</h4>${finalWinners.length?finalWinners.map(id=>slot(id,true,false,games[2])).join(''):slot(null,false,false,games[2])}</div></div>`;}
const resultNames=ids=>ids.map(id=>bowler(id)?.name).filter(Boolean).join(' / ');
function renderBrackets(){$('bracketLists').innerHTML=Object.keys(WINDOWS).map(key=>`<div class="bracket-group"><h2>${esc(TITLES[key])}</h2>${state.brackets[key].length?state.brackets[key].map((ids,i)=>{const result=bracketResult(ids,key);return`<div class="card bracket-card"><h3>Bracket #${i+1}</h3>${bracketDiagram(ids,key)}${result?`<p><strong>1st:</strong> ${esc(resultNames(result.winners))} · <strong>2nd:</strong> ${esc(resultNames(result.seconds)||'—')}</p>`:'<p>No results yet.</p>'}</div>`}).join(''):'<div class="card">No brackets generated.</div>'}`).join('');const unused=state.bowlers.flatMap(b=>eventDefs.map(([key])=>{const n=(b.events[key]||0)-assigned(key,b.id);return n>0?`${b.name}: ${n} unused ${TITLES[key]}`:null})).filter(Boolean);$('bracketNotice').innerHTML=unused.length?`<p class="notice">Unused willingness is not charged: ${esc(unused.join(' · '))}</p>`:'';}
function dayBracketPayouts(keys,highCategory){const totals=new Map(),rowFor=bid=>{const row=totals.get(bid)||{id:bid,first:0,second:0,high:0,amount:0};totals.set(bid,row);return row};for(const key of keys)(state.brackets[key]||[]).forEach(ids=>{const result=bracketResult(ids,key);if(!result)return;const scratch=SCRATCH_KEYS.has(key),first=cents(scratch?state.config.scratchBracketFirst:state.config.bracketFirst),second=cents(scratch?state.config.scratchBracketSecond:state.config.bracketSecond);if(result.winners.length>1){const pool=first+second,share=Math.floor(pool/result.winners.length),remainder=pool%result.winners.length;result.winners.forEach((id,index)=>{const row=rowFor(id);row.first++;row.amount+=share+(index<remainder?1:0)})}else{const winner=rowFor(result.winner);winner.first++;winner.amount+=first;result.seconds.forEach(id=>{const runner=rowFor(id);runner.second++;runner.amount+=Math.floor(second/result.seconds.length)})}});for(const award of highAwards().filter(a=>a.category===highCategory)){const row=rowFor(award.id);row.high+=award.amount;row.amount+=award.amount}return alphabetical([...totals.values()].map(row=>({...row,name:bowler(row.id)?.name||'Unknown'})));}
function renderDayResults(title,keys,highCategory){
  const saturday=keys===SATURDAY_KEYS,games=saturday?[1,2,3,4]:[5,6,7],payoutRows=dayBracketPayouts(keys,highCategory);
  const payouts=payoutRows.length?`<div class="card"><h3>${esc(tr('Daily payout summary'))}</h3><div class="table-wrap"><table><thead><tr><th>${esc(tr('Bowler'))}</th><th>${esc(tr('First places'))}</th><th>${esc(tr('Second places'))}</th><th>${esc(tr('High Game payout'))}</th><th>${esc(tr('Total payout'))}</th></tr></thead><tbody>${payoutRows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.first}</td><td>${r.second}</td><td class="money">${money(r.high)}</td><td class="money"><strong>${money(r.amount)}</strong></td></tr>`).join('')}</tbody></table></div><p><small>${esc(tr('Doubles spans all seven games and remains in the full Reports & payouts summary.'))}</small></p></div>`:`<div class="card"><p>${esc(tr('No completed payouts yet.'))}</p></div>`;
  const players=alphabetical(state.bowlers.filter(b=>games.some(g=>requiredGames(b).has(g))));
  const scores=`<div class="card"><h3>${esc(tr('Scores'))}</h3><div class="table-wrap"><table><thead><tr><th>${esc(tr('Bowler'))}</th>${games.map(g=>`<th>G${g}</th>`).join('')}</tr></thead><tbody>${players.map(b=>`<tr><td><strong>${esc(b.name)}</strong><br><small>+${b.handicap}</small></td>${games.map(g=>`<td>${has(b,g)?score(b,g):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
  const brackets=keys.map(key=>`<div class="bracket-group"><h2>${esc(tr(TITLES[key]))}</h2>${(state.brackets[key]||[]).length?(state.brackets[key]||[]).map((ids,i)=>{const result=bracketResult(ids,key);return`<div class="card bracket-card"><h3>Bracket #${i+1}</h3>${bracketDiagram(ids,key)}${result?`<p><strong>${esc(tr('1st'))}:</strong> ${esc(resultNames(result.winners))} · <strong>${esc(tr('2nd'))}:</strong> ${esc(resultNames(result.seconds)||'—')}</p>`:`<p>${esc(tr('No results yet.'))}</p>`}</div>`}).join(''):`<div class="card"><p>${esc(tr('No brackets generated.'))}</p></div>`}`).join('');
  return`<section class="day-results"><div class="card day-results-heading"><h2>${esc(tr(title))}</h2></div>${payouts}${scores}${brackets}</section>`;
}
function renderManagerDay(day){const saturday=day==='saturday',target=$(saturday?'saturdayResults':'sundayResults');target.innerHTML=renderDayResults(saturday?'Saturday results':'Sunday results',saturday?SATURDAY_KEYS:SUNDAY_KEYS,saturday?'satHigh':'sunHigh');}
function bracketHistory(keys){const groups=new Map(),opponents=new Map();for(const key of keys)for(const ids of state.brackets[key]||[]){for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++)groups.set(pairKey(ids[i],ids[j]),(groups.get(pairKey(ids[i],ids[j]))||0)+1);for(let i=0;i<ids.length;i+=2)if(ids[i+1])opponents.set(pairKey(ids[i],ids[i+1]),(opponents.get(pairKey(ids[i],ids[i+1]))||0)+1)}return{groups,opponents};}
const hasSaturdayScores=()=>state.bowlers.some(b=>(b.scores||[]).slice(0,4).some(score=>score!==null&&score!==''&&score!==undefined));
function resetBracketsAfterRosterChange(){if(state.saturdayLocked||hasSaturdayScores()){for(const key of SUNDAY_KEYS)state.brackets[key]=[];state.generated=SATURDAY_KEYS.some(key=>state.brackets[key].length)}else{state.brackets=blankBrackets();state.generated=false;}}
function renderBracketResultsExport(){const bracketKeys=Object.keys(WINDOWS),participants=alphabetical(state.bowlers.map(b=>{const played=bracketKeys.reduce((n,key)=>n+assigned(key,b.id),0),won=bracketKeys.reduce((n,key)=>n+(state.brackets[key]||[]).filter(ids=>bracketResult(ids,key)?.winners.includes(b.id)).length,0);return{...b,played,won};}).filter(b=>b.played));const summary=participants.map(b=>`<tr><td>${esc(b.name)}</td><td>${b.played}</td><td>${b.won}</td></tr>`).join('');const diagrams=bracketKeys.map(key=>{const cards=(state.brackets[key]||[]).map((ids,i)=>{const result=bracketResult(ids,key);return`<article class="export-bracket"><h3>${esc(tr(TITLES[key]))} · Bracket #${i+1}</h3>${bracketDiagram(ids,key)}${result?`<p><strong>${esc(tr('1st'))}:</strong> ${esc(resultNames(result.winners))} &nbsp; <strong>${esc(tr('2nd'))}:</strong> ${esc(resultNames(result.seconds)||'—')}</p>`:'<p>'+esc(tr('No results yet.'))+'</p>'}</article>`}).join('');return cards?`<section class="export-group"><h2>${esc(tr(TITLES[key]))}</h2>${cards}</section>`:''}).join('');$('bracketResultsPrint').innerHTML=`<div class="export-brand"><img src="../assets/brackets-logo.png?v=20260922" alt="Brackets by ProDrillOS"><div><div class="eyebrow">DE LA ROSA MASTERS</div><h1>${esc(tr('Bracket results'))}</h1><p>${new Date().toLocaleDateString(language==='es'?'es-MX':'en-US',{dateStyle:'long'})}</p></div></div><section class="export-summary"><h2>${esc(tr('Bracket participation summary'))}</h2><table><thead><tr><th>${esc(tr('Bowler'))}</th><th>${esc(tr('Brackets played'))}</th><th>${esc(tr('Brackets won'))}</th></tr></thead><tbody>${summary}</tbody></table></section>${diagrams}`;}
function printBracketResults(){renderBracketResultsExport();document.body.classList.add('bracket-results-print');$('bracketResultsPrint').setAttribute('aria-hidden','false');const cleanup=()=>{document.body.classList.remove('bracket-results-print');$('bracketResultsPrint').setAttribute('aria-hidden','true')};window.addEventListener('afterprint',cleanup,{once:true});window.print();}
function printPayoutReport(){document.body.classList.add('payout-report-print');const cleanup=()=>document.body.classList.remove('payout-report-print');window.addEventListener('afterprint',cleanup,{once:true});window.print();}
function awardBelongsToDay(award,day){return day==='saturday'?SATURDAY_KEYS.includes(award.category)||award.category==='satHigh':SUNDAY_KEYS.includes(award.category)||award.category==='sunHigh'||award.category==='doubles';}
function dayFinancial(person,day){const dayCharges=(person.charges||[]).filter(c=>c.day===day),dayWinnings=(person.winnings||[]).filter(w=>awardBelongsToDay(w,day)),due=dayCharges.reduce((n,c)=>n+c.amount,0),paid=day==='saturday'?person.saturdayPaid:person.sundayPaid,won=dayWinnings.reduce((n,w)=>n+Number(w.amount||0),0),outstanding=paid?0:due;return{charges:dayCharges,winnings:dayWinnings,due,paid,won,outstanding,settlement:won-outstanding};}
function printDayPayouts(day){const label=tr(day==='saturday'?'Saturday':'Sunday'),rows=alphabetical(state.bowlers.map(personal)).map(person=>({person,day:dayFinancial(person,day)})).filter(x=>x.day.due||x.day.won),body=rows.map(({person,day:d})=>`<tr><td><strong>${esc(person.name)}</strong></td><td>${d.charges.map(c=>esc(c.label)).join('<br>')||'—'}</td><td class="money">${money(d.due)}</td><td>${tr(d.paid?'Yes':'No')}</td><td>${d.winnings.map(w=>`${esc(w.description)} ${money(w.amount)}`).join('<br>')||'—'}</td><td class="money">${money(d.won)}</td><td class="money ${d.settlement>0?'balance-positive':d.settlement<0?'balance-negative':'balance-zero'}">${d.settlement>=0?'+':''}${money(d.settlement)}</td></tr>`).join('');$('bracketResultsPrint').innerHTML=`<div class="export-brand"><img src="../assets/brackets-logo.png?v=20260922" alt="Brackets by ProDrillOS"><div><div class="eyebrow">DE LA ROSA MASTERS</div><h1>${esc(label)} · ${esc(tr('Payout summary'))}</h1><p>${new Date().toLocaleDateString(language==='es'?'es-MX':'en-US',{dateStyle:'long'})}</p></div></div><section class="export-summary"><table><thead><tr><th>${esc(tr('Bowler'))}</th><th>${esc(tr('Why they pay'))}</th><th>${esc(tr('Total due'))}</th><th>${esc(tr('Paid'))}</th><th>${esc(tr('Winnings'))}</th><th>${esc(tr('Total won'))}</th><th>${esc(tr('Settle now'))}</th></tr></thead><tbody>${body}</tbody></table></section>`;document.body.classList.add('bracket-results-print');$('bracketResultsPrint').setAttribute('aria-hidden','false');const cleanup=()=>{document.body.classList.remove('bracket-results-print');$('bracketResultsPrint').setAttribute('aria-hidden','true')};window.addEventListener('afterprint',cleanup,{once:true});window.print();}
function requiredGames(b){if(b.events.doubles)return new Set([1,2,3,4,5,6,7]);const games=new Set();for(const key of Object.keys(WINDOWS))if(b.events[key])WINDOWS[key].forEach(g=>games.add(g));if(b.events.satHigh)[1,2,3,4].forEach(g=>games.add(g));if(b.events.sunHigh)[5,6,7].forEach(g=>games.add(g));return games;}
function renderScores(){$('scoreHead').innerHTML='<tr><th>Bowler</th>'+[1,2,3,4].map(g=>`<th>Sat G${g}</th>`).join('')+[1,2,3].map(g=>`<th class="score-separator">Sun G${g}</th>`).join('')+'</tr>';$('scoreRows').innerHTML=alphabetical(state.bowlers).map(b=>{const required=requiredGames(b);return`<tr><td><strong>${esc(b.name)}</strong><br><small>+${b.handicap}</small></td>${[1,2,3,4,5,6,7].map((g,i)=>`<td class="${g===5?'score-separator':''}">${required.has(g)?state.saturdayLocked&&g<=4?`<span class="locked-score">${b.scores[i]??'—'} <span aria-label="Locked">🔒</span></span>`:`<input aria-label="${esc(b.name)} game ${g}" data-score="${b.id}" data-game="${i}" type="number" min="0" max="300" value="${b.scores[i]??''}">`:'<span class="not-required">—</span>'}</td>`).join('')}</tr>`}).join('');const locked=!!state.saturdayLocked;$('lockSaturday').disabled=locked;$('lockSaturday').textContent=tr(locked?'Saturday scores locked':'Lock Saturday scores');$('saturdayLockStatus').classList.toggle('hidden',!locked);$('saturdayLockStatus').textContent=locked?tr('Saturday games 1–4 and their brackets are permanently protected. Only Sunday scores can be added.'):'';$('generateBrackets').disabled=locked;}
function standingCard(title,players,value,awardList){const sorted=players.filter(x=>Number.isFinite(value(x))).sort((a,b)=>value(b)-value(a));return`<div class="card"><h2>${esc(title)}</h2>${sorted.length?`<ol>${sorted.map(x=>`<li class="team-rank"><strong>${esc(x.name||x.players.map(p=>p.name).join(' & '))}</strong> — ${value(x)}</li>`).join('')}</ol><p>${awardList.map(a=>`${esc(bowler(a.id)?.name||'')}: ${money(a.amount)}`).join('<br>')}</p>`:'<p>No results yet.</p>'}</div>`;}
function renderHigh(){const sat=state.bowlers.filter(b=>b.events.satHigh),sun=state.bowlers.filter(b=>b.events.sunHigh);$('highResults').innerHTML=standingCard(tr('Saturday High Game'),sat,b=>[1,2,3,4].every(g=>has(b,g))?Math.max(...[1,2,3,4].map(g=>score(b,g))):NaN,highAwards().filter(a=>a.category==='satHigh'))+standingCard(tr('Sunday High Game'),sun,b=>[5,6,7].every(g=>has(b,g))?Math.max(...[5,6,7].map(g=>score(b,g))):NaN,highAwards().filter(a=>a.category==='sunHigh'));}
function renderTeams(){$('bowlerOptions').innerHTML=alphabetical(state.bowlers.filter(b=>b.events.doubles)).map(b=>`<option value="${esc(b.name)}"></option>`).join('');const teams=validTeams();$('teamResults').innerHTML=`<div class="card"><h2>${tr('Doubles')} · ${tr('Doubles 7-game series')}</h2>${state.teams.length?`<ol>${state.teams.map((ids,i)=>{const t=teams.find(x=>x.id==='team-'+i);return`<li class="team-rank"><strong>${ids.map(x=>esc(bowler(x)?.name||'Unknown')).join(' &amp; ')}</strong> — ${t&&Number.isFinite(teamSeries(t))?teamSeries(t):'—'} <button class="danger" data-remove-team="${i}">${tr('Remove')}</button></li>`}).join('')}</ol>`:'<p>No teams registered.</p>'}</div>`;}
function renderReports(){const rows=alphabetical(state.bowlers).map(personal);$('reportRows').innerHTML=rows.map(r=>{const hasScores=bowler(r.id)?.scores?.some(score=>score!==null&&score!==''&&score!==undefined);return`<tr class="${hasScores?'':'no-entered-scores'}"><td><strong>${esc(r.name)}</strong></td><td>${r.charges.map(c=>esc(c.label)).join('<br>')||'—'}</td><td class="money">${money(r.due)}</td><td>${tr(r.saturdayPaid?'Yes':'No')}<br><small>${money(r.saturdayDue)}</small></td><td>${tr(r.sundayPaid?'Yes':'No')}<br><small>${money(r.sundayDue)}</small></td><td class="money balance-negative">${money(r.outstanding)}</td><td>${r.winnings.map(w=>`${esc(w.description)} ${money(w.amount)}`).join('<br>')||'—'}</td><td class="money">${money(r.won)}</td><td class="money ${r.settlement>0?'balance-positive':r.settlement<0?'balance-negative':'balance-zero'}">${r.settlement>=0?'+':''}${money(r.settlement)}</td></tr>`}).join('');const totals=rows.reduce((x,r)=>({due:x.due+r.due,paid:x.paid+(r.saturdayPaid?r.saturdayDue:0)+(r.sundayPaid?r.sundayDue:0),out:x.out+r.outstanding,won:x.won+r.won,settle:x.settle+r.settlement}),{due:0,paid:0,out:0,won:0,settle:0});$('reportTotals').innerHTML=[['Total charges',totals.due],['Payments received',totals.paid],['Outstanding',totals.out],['Total winnings',totals.won],['Total to settle now',totals.settle]].map(([k,v])=>`<div>${esc(k)}<strong>${v===totals.settle&&v>0?'+':''}${money(v)}</strong></div>`).join('');}
function viewerDiagram(ids,key,data){const byId=new Map(data.bowlers.map(b=>[b.id,b])),games=WINDOWS[key],scratch=SCRATCH_KEYS.has(key),maxGame=SUNDAY_KEYS.includes(key)?7:4,vscore=(bid,g,withHandicap=!scratch)=>{const b=byId.get(bid),raw=b?.scores?.[g-1];return raw===null||raw===''||raw===undefined?null:Number(raw)+(withHandicap?Number(b.handicap||0):0)},vduel=(players,g)=>{if(players.some(x=>!x))return null;for(let decidingGame=g;decidingGame<=maxGame;decidingGame++){if(players.some(x=>vscore(x,decidingGame)===null))return null;const high=Math.max(...players.map(x=>vscore(x,decidingGame))),w=players.filter(x=>vscore(x,decidingGame)===high);if(w.length===1)return w[0]}return null},r1=[];for(let i=0;i<8;i+=2)r1.push(vduel(ids.slice(i,i+2),games[0]));const r2=[vduel(r1.slice(0,2),games[1]),vduel(r1.slice(2,4),games[1])],complete=r2.every(id=>id&&games.every(g=>vscore(id,g,true)!==null));let finalWinners=[];if(complete){const metrics=id=>[vscore(id,games[2]),games.reduce((sum,g)=>sum+vscore(id,g,true),0),Math.max(...games.map(g=>vscore(id,g,true)))],ranked=r2.map(id=>({id,metrics:metrics(id)})).sort((a,b)=>b.metrics[0]-a.metrics[0]||b.metrics[1]-a.metrics[1]||b.metrics[2]-a.metrics[2]);finalWinners=ranked.filter(entry=>entry.metrics.every((value,index)=>value===ranked[0].metrics[index])).map(entry=>entry.id)}const slot=(bid,won,lost,g)=>`<div class="slot ${won?'win':lost?'lose':'pending'}">${esc(byId.get(bid)?.name||'Pending')}${bid&&vscore(bid,g)!==null?` <small>${vscore(bid,g)}</small>`:''}</div>`,matches=(players,winners,g)=>players.reduce((html,_,i)=>{if(i%2)return html;const selected=winners[Math.floor(i/2)],won=bid=>Array.isArray(selected)?selected.includes(bid):selected===bid,lost=bid=>!!selected&&!won(bid);return html+`<div class="match-box">${slot(players[i],won(players[i]),lost(players[i]),g)}${slot(players[i+1],won(players[i+1]),lost(players[i+1]),g)}</div>`},'');return`<div class="bracket-diagram"><div class="bracket-round"><h4>Game ${games[0]}</h4>${matches(ids,r1,games[0])}</div><div class="bracket-round"><h4>Game ${games[1]} · Semifinal</h4>${matches(r1,r2,games[1])}</div><div class="bracket-round"><h4>Game ${games[2]} · Final</h4>${matches(r2,[finalWinners],games[2])}</div><div class="bracket-round round-winner"><h4>Winner</h4>${finalWinners.length?finalWinners.map(id=>slot(id,true,false,games[2])).join(''):slot(null,false,false,games[2])}</div></div>`;}
function viewerPersonal(data,bowlerId){const b=data.bowlers.find(x=>x.id===bowlerId);if(!b)return null;const saturdayPaid=b.saturdayPaid??b.paid??false,sundayPaid=b.sundayPaid??false,cs=[];for(const key of Object.keys(WINDOWS)){const n=(data.brackets?.[key]||[]).reduce((sum,ids)=>sum+ids.filter(x=>x===b.id).length,0),price=SCRATCH_KEYS.has(key)?data.config.scratchBracketBuyin:data.config.bracketBuyin;if(n)cs.push({label:`${TITLES[key]}: ${n} × $${Number(price).toFixed(2)}`,amount:n*cents(price),day:SUNDAY_KEYS.includes(key)?'sunday':'saturday'});}if(b.events?.satHigh)cs.push({label:`Saturday High Game: $${Number(data.config.satHighBuyin).toFixed(2)}`,amount:cents(data.config.satHighBuyin),day:'saturday'});if(b.events?.sunHigh)cs.push({label:`Sunday High Game: $${Number(data.config.sunHighBuyin).toFixed(2)}`,amount:cents(data.config.sunHighBuyin),day:'sunday'});const teamCount=(data.teams||[]).filter(ids=>ids.includes(b.id)).length;if(teamCount)cs.push({label:`Doubles: ${teamCount} × $${Number(data.config.doublesBuyin).toFixed(2)}`,amount:teamCount*cents(data.config.doublesBuyin),day:'saturday'});const winnings=(data.awards||[]).filter(a=>a.id===b.id),saturdayDue=cs.filter(x=>x.day==='saturday').reduce((n,x)=>n+x.amount,0),sundayDue=cs.filter(x=>x.day==='sunday').reduce((n,x)=>n+x.amount,0),due=saturdayDue+sundayDue,won=winnings.reduce((n,x)=>n+Number(x.amount||0),0),outstanding=(saturdayPaid?0:saturdayDue)+(sundayPaid?0:sundayDue);return{id:b.id,name:b.name,paid:saturdayPaid&&sundayPaid,saturdayPaid,sundayPaid,charges:cs,winnings,saturdayDue,sundayDue,due,won,outstanding,settlement:won-outstanding};}
function renderViewer(data,personalData,selectedId=personalData?.id){
  const people=data?.bowlers||[];if(!data){$('viewerContent').innerHTML='<div class="card"><p>Results are not available yet.</p></div>';return;}
  const selected=people.find(b=>b.id===selectedId);
  if(selected&&!personalData)personalData=viewerPersonal(data,selected.id);
  const chooser=`<div class="card"><h2>${tr('Your bowler')}</h2><p>${tr('Choose your bowler to see your balance, scores and only the brackets you are competing in.')}</p><div class="form-grid compact"><label>${tr('Bowler')}<select id="viewerBowler"><option value="">${tr('Choose a bowler')}</option>${people.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(b=>`<option value="${esc(b.id)}" ${b.id===selectedId?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><button id="viewerSelect">${tr('Show my results')}</button></div><p id="viewerSelectStatus" class="error"></p></div>`;
  const teams=selected?(data.teams||[]).filter(ids=>ids.includes(selected.id)).map(ids=>ids.map(x=>people.find(b=>b.id===x)?.name||'Unknown').join(' & ')):[];
  const dayPanel=day=>{const saturday=day==='saturday',keys=saturday?SATURDAY_KEYS:SUNDAY_KEYS,games=saturday?[1,2,3,4]:[5,6,7],financial=personalData?dayFinancial(personalData,day):null,entries=selected?keys.flatMap(key=>(data.brackets?.[key]||[]).map((ids,index)=>({ids,index,key})).filter(x=>x.ids.includes(selected.id))):[],brackets=entries.map(x=>`<div class="bracket-group"><h2>${esc(tr(TITLES[x.key]))} · Bracket #${x.index+1}</h2><div class="card bracket-card">${viewerDiagram(x.ids,x.key,data)}</div></div>`).join(''),scores=selected?`<div class="card"><h2>${tr('Scores')} — ${esc(selected.name)}</h2><div class="table-wrap"><table><thead><tr><th>${tr('Bowler')}</th>${games.map(g=>`<th>G${g}</th>`).join('')}</tr></thead><tbody><tr><td>${esc(selected.name)}<br><small>+${selected.handicap}</small></td>${games.map(g=>`<td>${selected.scores?.[g-1]==null?'—':Number(selected.scores[g-1])+Number(selected.handicap||0)}</td>`).join('')}</tr></tbody></table></div></div>`:'',balance=financial?`<div class="card"><h2>${tr('Daily balance')} — ${esc(personalData.name)}</h2><h3>${tr('Day charges')}: ${money(financial.due)}</h3><p>${financial.charges.map(c=>`• ${esc(c.label)}: ${money(c.amount)}`).join('<br>')||tr('No charges')}</p><p><strong>${tr(saturday?'Saturday paid':'Sunday paid')}: ${tr(financial.paid?'Yes':'No')} · ${tr('Outstanding')}: ${money(financial.outstanding)}</strong></p><h3>${tr('Day winnings')}: ${money(financial.won)}</h3><p>${financial.winnings.map(w=>`• ${esc(w.description)}: ${money(w.amount)}`).join('<br>')||tr('No winnings')}</p><h3 class="${financial.settlement>0?'balance-positive':financial.settlement<0?'balance-negative':'balance-zero'}">${tr('Settle now')}: ${financial.settlement>=0?'+':''}${money(financial.settlement)}</h3></div>`:'';return`<section class="viewer-day ${viewerDay===day?'active':''}" data-viewer-panel="${day}">${balance}${scores}${brackets||selected?brackets:''}${!saturday&&selected?`<div class="card"><h2>${tr('Doubles')}</h2><p>${tr('Seven-game Doubles results are finalized on Sunday.')}</p>${teams.length?teams.map(esc).join('<br>'):tr('No Doubles teams.')}</div>`:''}</section>`};
  if(!['saturday','sunday'].includes(viewerDay))viewerDay='saturday';
  const dayViews=selected?`<nav class="tabs viewer-day-tabs"><button data-viewer-day="saturday" class="${viewerDay==='saturday'?'active':''}">${tr('Saturday')}</button><button data-viewer-day="sunday" class="${viewerDay==='sunday'?'active':''}">${tr('Sunday')}</button></nav>${dayPanel('saturday')}${dayPanel('sunday')}`:'';
  $('viewerContent').innerHTML=`<div class="card viewer-hero"><h2>${esc(tournamentName)}</h2><p>${tr('Saturday')}: 4 games · ${tr('Sunday')}: 3 games</p></div>${chooser}${dayViews}`;
  $('viewerSelect').addEventListener('click',async()=>{const bowlerId=$('viewerBowler').value;if(!bowlerId){$('viewerSelectStatus').textContent=tr('Choose a bowler.');return;}try{$('viewerSelect').disabled=true;const profile=permanentRoster.find(p=>p.id===bowlerId);if(profile&&!profile.claimed_by_me){const message=language==='es'?`¿Confirma que usted es ${profile.name}? Esta selección se guardará para esta liga.`:`Confirm that you are ${profile.name}. This choice will be saved for this league.`;if(!window.confirm(message)){$('viewerSelect').disabled=false;return;}await api('/roster/claim','POST',{competitionId:competition.id,profileId:profile.id,confirm:true});permanentRoster=await api('/roster?competition_id='+encodeURIComponent(competition.id));}const linked=await api('/balance','POST',{competitionId:competition.id,bowlerId});renderViewer(data,linked.personal||viewerPersonal(data,bowlerId),bowlerId);translate();}catch(error){$('viewerSelectStatus').textContent=error.message;$('viewerSelect').disabled=false;}});
  document.querySelectorAll('[data-viewer-day]').forEach(button=>button.addEventListener('click',()=>{viewerDay=button.dataset.viewerDay;document.querySelectorAll('[data-viewer-day]').forEach(x=>x.classList.toggle('active',x===button));document.querySelectorAll('[data-viewer-panel]').forEach(x=>x.classList.toggle('active',x.dataset.viewerPanel===viewerDay));}));translate();
}
function render(){state.language=language;renderConfig();renderEventFields(editing?bowler(editing):undefined);renderRoster();renderBrackets();renderScores();renderHigh();renderTeams();renderReports();$('competitionSummaryCards').innerHTML=competitionSummaryMarkup(state);if($('saturday').classList.contains('active'))renderManagerDay('saturday');if($('sunday').classList.contains('active'))renderManagerDay('sunday');translate();}
function resetForm(){$('bowlerForm').reset();$('handicap').value=0;$('bowlerMembership').value='';editing=null;$('bowlerHeading').textContent=tr('Register a bowler');$('saveBowler').textContent=tr('Add bowler');$('cancelEdit').classList.add('hidden');renderEventFields();}
async function enter(){const rows=await api('/competitions'),found=rows.find(c=>requestedCompetition?c.id===requestedCompetition:c.name.trim().toLocaleLowerCase()===DEFAULT_NAME.toLocaleLowerCase());competition=found||null;if(found){tournamentName=found.name;document.querySelector('.header-copy h1').textContent=tournamentName;}if(!found){show(role==='superadmin'?'setupView':'viewerView');if(role!=='superadmin')$('viewerContent').innerHTML='<div class="card"><p>This tournament has not been created yet.</p></div>';return;}permanentRoster=await api('/roster?competition_id='+encodeURIComponent(found.id));if(requestedSession){const archived=await api('/session?id='+encodeURIComponent(requestedSession));if(archived.competitionId!==found.id)throw new Error('Saved session does not belong to this tournament.');document.querySelector('.header-copy h1').textContent=found.name+' · '+archived.label;if(found.can_manage){archiveMode=true;state=normalize(archived.results);language=state.language||language;show('managerView');render();document.querySelectorAll('#registration input,#registration button,#brackets button,#scoring input,#scoring button,#doubles input,#doubles button').forEach(control=>control.disabled=true);$('saveState').textContent='Saved session · read only';}else{show('viewerView');renderViewer(archived.results,archived.personal||viewerPersonal(archived.results,archived.bowlerId),archived.bowlerId);}return;}if(found.can_manage){$('permanentRosterNames').innerHTML=permanentRoster.filter(p=>p.active).map(p=>'<option value="'+esc(p.name)+'"></option>').join('');const saved=await api('/state?id='+encodeURIComponent(found.id));if(saved&&saved.format!==FORMAT)throw new Error('This competition contains a different tournament format.');state=saved?normalize(saved):fresh();language=state.language||language;show('managerView');render();}else{const result=await api('/results?id='+encodeURIComponent(found.id));show('viewerView');renderViewer(result.results,result.personal,result.bowlerId);}}
async function identify(u){user=u||null;$('authButton').textContent=tr(user?'Log out':'Log in');if(!user){show('authView');translate();return;}role=(await api('/me')).role||'user';$('superAdminTools').classList.toggle('hidden',role!=='superadmin');await enter();translate();}

$('language').addEventListener('change',e=>{language=e.target.value;localStorage.setItem('dlr-language',language);if(state)state.language=language;translate();if(competition?.can_manage)scheduleSave();});
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const credentials={email:$('email').value.trim().toLowerCase(),password:$('password').value};await resetExpiredSession();let r=await client.auth.signIn.email(credentials);if(r.error&&/expired|session|refresh/i.test(r.error.message||String(r.error))){needsSessionReset=true;await resetExpiredSession();r=await client.auth.signIn.email(credentials);}if(r.error)throw r.error;user=r.data.user;handoffToken=r.data?.token||r.data?.session?.token||handoffToken;if(user&&handoffToken)sessionStorage.setItem('dlr-auth-handoff',JSON.stringify({user,token:handoffToken}));await token();$('password').value='';notice('');await identify(r.data.user);}catch(err){if(/expired|session|refresh/i.test(err.message||String(err)))needsSessionReset=true;notice(err.message,true);}});
$('authButton').addEventListener('click',async()=>{if(user){await client.auth.signOut();sessionStorage.removeItem('dlr-auth-handoff');handoffToken=null;user=null;competition=null;show('authView');translate();}else show('authView');});
