$('saveDlrSession').addEventListener('click',async()=>{const button=$('saveDlrSession');button.disabled=true;try{await saveTournamentSession();}catch(error){$('dlrSessionStatus').textContent=error.message;}finally{button.disabled=false;}});
$('startDlrSession').addEventListener('click',async()=>{const button=$('startDlrSession');button.disabled=true;try{await startTournamentSession();}catch(error){$('dlrSessionStatus').textContent=error.message;}finally{button.disabled=false;}});

async function restoreBracketsSession(){
  const handoff=readAuthHandoff();
  if(handoff){user=handoff.user;handoffToken=handoff.token;return user;}
  // A navigation can happen immediately after Neon refreshes its cookie. Give that
  // persisted session a brief chance to become visible before showing another login.
  for(let attempt=0;attempt<4;attempt++){
    const restored=await client.auth.getSession();
    if(restored.error)throw restored.error;
    if(restored.data?.user){
      user=restored.data.user;
      const currentToken=await client.auth.token();
      if(!currentToken.error&&currentToken.data?.token)return user;
    }
    if(attempt<3)await new Promise(resolve=>setTimeout(resolve,150*(attempt+1)));
  }
  return null;
}
(async()=>{$('dlrSessionDate').value=new Date().toLocaleDateString('en-CA');translate();show('loadingView');try{await identify(await restoreBracketsSession());}catch(e){user=null;needsSessionReset=true;notice('Session expired. Log in again.',true);show('authView');translate();}})();

